interface Interceptor { void before(); void after(); }
class LogInterceptor implements Interceptor {
    public void before() { System.out.println("[cglib before]"); }
    public void after() { System.out.println("[cglib after]"); }
}
// 被代理的目标类（无需接口 —— CGLIB 直接代理类）
class Target {
    public String hello(String name) { return "hello " + name; }
}
// 模拟 CGLIB 增强器：生成目标类的【子类】并重写方法，在 super 调用前后织入通知
class Target_Enhancer extends Target {
    private Interceptor ic;
    Target_Enhancer(Interceptor ic) { this.ic = ic; }
    @Override public String hello(String name) {
        ic.before();
        String r = super.hello(name);
        ic.after();
        return r;
    }
}
public class Main {
    public static void main(String[] a) {
        Target proxy = new Target_Enhancer(new LogInterceptor());
        System.out.println(proxy.hello("bob"));
        System.out.println("proxy is subclass of Target: " + (proxy instanceof Target));
        System.out.println("proxy class name: " + proxy.getClass().getSimpleName());
    }
}
